const okInt=(n,min)=>Number.isSafeInteger(n)&&n>=min;
const isObj=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
class Orders {
  constructor(stock,prices={}) { this.stock={...stock};this.prices={...prices};this.rows={}; }
  expire(now) {
    if(!okInt(now,0)) throw new RangeError('now');
    for(const r of Object.values(this.rows)) {
      if(!r.expired&&now>=r.deadline) {r.expired=true;this.stock[r.sku]=(this.stock[r.sku]||0)+r.qty-r.fulfilled;}
    }
  }
  reserve(id,sku,qty,now=0,ttl=10) {
    if(!okInt(qty,1)) throw new RangeError('qty');
    if(!okInt(ttl,1)) throw new RangeError('ttl');
    if(!okInt(now,0)) throw new RangeError('now');
    this.expire(now);
    if(Object.hasOwn(this.rows,id)) {const r=this.rows[id];return !r.expired&&r.sku===sku&&r.qty===qty;}
    if((this.stock[sku]||0)<qty) return false;
    this.stock[sku]-=qty;this.rows[id]={sku,qty,deadline:now+ttl,expired:false,fulfilled:0,refunded:0};return true;
  }
  cents(sku,qty) {return BigInt(this.prices[sku]||'0')*BigInt(qty);}
  fulfill(id,qty,now=0) {
    if(!okInt(qty,1)) throw new RangeError('qty');
    if(!okInt(now,0)) throw new RangeError('now');
    this.expire(now);
    const r=Object.hasOwn(this.rows,id)?this.rows[id]:null;
    if(!r||r.expired||qty>r.qty-r.fulfilled) return null;
    r.fulfilled+=qty;return this.cents(r.sku,qty);
  }
  refund(id,qty) {
    if(!okInt(qty,1)) throw new RangeError('qty');
    const r=Object.hasOwn(this.rows,id)?this.rows[id]:null;
    if(!r||qty>r.fulfilled-r.refunded) return null;
    r.refunded+=qty;this.stock[r.sku]=(this.stock[r.sku]||0)+qty;return this.cents(r.sku,qty);
  }
  replay(events) {
    if(!Array.isArray(events)) throw new RangeError('events');
    const w=new Orders(this.stock,this.prices);
    w.rows=Object.fromEntries(Object.entries(this.rows).map(([k,r])=>[k,{...r}]));
    if(this.events!==undefined) w.events=Object.fromEntries(Object.entries(this.events));
    const ops={reserve:'reserve',fulfill:'fulfill',refund:'refund',expire:'expire'};
    for(const e of events) {
      if(!isObj(e)||typeof e.event!=='string'||typeof e.op!=='string'||!Array.isArray(e.args)||!Object.hasOwn(ops,e.op)) throw new RangeError('event');
      const sig=JSON.stringify([e.op,e.args]);
      if(w.events!==undefined&&Object.hasOwn(w.events,e.event)) {
        if(w.events[e.event]!==sig) throw new RangeError('conflict');
        continue;
      }
      let res;
      try {res=w[e.op](...e.args);} catch(err) {throw new RangeError('args');}
      if(e.op!=='expire'&&(res===false||res===null)) throw new RangeError('rejected');
      if(w.events===undefined) w.events={};
      Object.defineProperty(w.events,e.event,{value:sig,enumerable:true,writable:true,configurable:true});
    }
    this.stock=w.stock;this.rows=w.rows;
    if(w.events!==undefined) this.events=w.events;
  }
  dumps() {
    const o={version:2,stock:this.stock,prices:this.prices,rows:this.rows};
    if(this.events!==undefined) o.events=this.events;
    return JSON.stringify(o);
  }
  static loads(text) {
    let d;
    try {d=JSON.parse(text);} catch(e) {throw new RangeError('snapshot');}
    if(!isObj(d)) throw new RangeError('snapshot');
    if(d.version!==2) throw new RangeError('version');
    if(!isObj(d.stock)||!isObj(d.prices)||!isObj(d.rows)) throw new RangeError('fields');
    for(const v of Object.values(d.stock)) if(!okInt(v,0)) throw new RangeError('stock');
    for(const v of Object.values(d.prices)) if(typeof v!=='string'||!/^[0-9]+$/.test(v)) throw new RangeError('prices');
    for(const r of Object.values(d.rows)) {
      if(!isObj(r)||typeof r.sku!=='string'||!okInt(r.qty,1)||!okInt(r.deadline,0)||typeof r.expired!=='boolean'
        ||!okInt(r.fulfilled,0)||!okInt(r.refunded,0)||r.fulfilled>r.qty||r.refunded>r.fulfilled) throw new RangeError('row');
    }
    if(d.events!==undefined&&!isObj(d.events)) throw new RangeError('events');
    const o=new Orders(d.stock,d.prices);
    o.rows=Object.fromEntries(Object.entries(d.rows).map(([k,r])=>[k,{sku:r.sku,qty:r.qty,deadline:r.deadline,expired:r.expired,fulfilled:r.fulfilled,refunded:r.refunded}]));
    if(d.events!==undefined) o.events=Object.fromEntries(Object.entries(d.events));
    return o;
  }
  available(sku,now) {
    if(now!==undefined) this.expire(now);
    return this.stock[sku]||0;
  }
}
module.exports={Orders};
